mapper.update:
UPDATE b_official 
SET gmt_modify = now()

    , name = #{name}


    , phone = #{phone}


    , email = #{email}


    , state = #{state}


    , image_url = #{imageUrl}


    , region_id = #{regionId}


    , specialty = #{specialty}


    , work_state = #{workState}


    , grade_id = #{gradeId}

WHERE id = #{id};

update b_official_evaluate set SET gmt_modify = now()

    , official_id = #{officialId}


    , adviser_id = #{adviserId}


    , professionalism = #{professionalism}


    , accuracy = #{accuracy}


    , accuracy = #{accuracy}


    , timely_communication = #{timelyCommunication}


    , collaboration_time = #{collaborationTime}


    , reason_low_score = #{reasonLowScore}


    , remark = #{remark}

where id = #{id}

mapper.select:
SELECT count(*)
FROM b_official
WHERE 1 = 1

    AND name = #{name}


    AND region_id = #{regionId}


    AND grade_id = #{gradeId}

;

SELECT * FROM (( SELECT ( @i := @i + 1 ) AS 'sort', t1.* FROM ( SELECT id, NAME, phone, email, state, image_url AS imageUrl, region_id AS regionId, specialty AS specialty, work_state AS workState, grade_id AS gradeId FROM b_official b WHERE 1 = 1 AND b.id IN ( SELECT id FROM b_official WHERE work_state = "NORMAL" ) ORDER BY b.`name` ) t1,( SELECT @i := 0 ) t ) UNION ( SELECT ( @i := @i + 1 ) AS 'sort', t2.* FROM ( SELECT id, NAME, phone, email, state, image_url AS imageUrl, region_id AS regionId, specialty AS specialty, work_state AS workState, grade_id AS gradeId FROM b_official b WHERE 1 = 1 AND b.id IN ( SELECT id FROM b_official WHERE work_state = "BUSY" ) ORDER BY b.`name` ) t2,( SELECT @i := 0 ) t ) UNION (SELECT (@j := @j + 1) AS 'sort', t3.* FROM (SELECT id, NAME, phone, email, state, image_url AS imageUrl, region_id AS regionId, specialty AS specialty, work_state AS workState, grade_id AS gradeId FROM b_official b WHERE b.work_state = "RESIGN" ORDER BY b.name) t3, (SELECT @j := 0) t ) ) a WHERE 1 = 1
AND name like '%${name}%'
AND regionId = #{regionId}
AND gradeId = #{gradeId}
ORDER BY a.sort LIMIT #{offset}, #{rows};

SELECT * FROM b_official_evaluate WHERE 1 = 1
AND official_id IN
#{item}
AND adviser_id = #{adviserId}
AND (collaboration_time between #{startCollaborationTime} and #{endCollaborationTime})
ORDER BY gmt_create DESC LIMIT #{pageNum}, #{pageSize};

SELECT count(*) FROM b_official_evaluate WHERE 1 = 1
AND official_id IN
#{item}
AND adviser_id = #{adviserId}
AND (collaboration_time between #{startCollaborationTime} and #{endCollaborationTime})

SELECT * FROM b_official_evaluate WHERE 1 = 1
AND official_id = #{officialId}
AND adviser_id = #{adviserId}
AND (collaboration_time between #{startCollaborationTime} and #{endCollaborationTime})
